% Build/publish monthly Stats, Chapter5 map, CCN, and Chapter4 DB for a month.
project='F:\AER_SHARED_PIPELINE';run_id=getenv('FULL_MONTH_RUN_ID');y=str2double(getenv('FULL_MONTH_YEAR'));m=str2double(getenv('FULL_MONTH_MONTH'));dates_file=getenv('FULL_MONTH_FINALIZED_DATES');if isempty(dates_file)||~isfile(dates_file),error('Coverage:MissingFinalizedDates','FULL_MONTH_FINALIZED_DATES is required.');end;run_root=fullfile(project,'runs',run_id);ym=sprintf('%04d%02d',y,m);addpath(fullfile(project,'code','config'),'-begin');addpath(fullfile(project,'code','functions'),'-begin');addpath(fullfile(project,'code','producers','calipso_stats'),'-begin');addpath(fullfile(project,'code','producers','chapter5'),'-begin');addpath(fullfile(project,'code','publishers'),'-begin');
ch5dir=fullfile(run_root,'staging','chapter5_month',sprintf('%04d',y),sprintf('%02d',m));if ~isfolder(ch5dir),mkdir(ch5dir);end;ch5stage=fullfile(ch5dir,['CHAPTER5_MAP_STATS_' ym '.mat']);build_chapter5_map_stats_month(y,m,ch5stage,dates_file);publish_chapter5_map_stats_month(y,m,ch5stage);
statsdir=fullfile(run_root,'staging','calipso_stats_monthly',sprintf('%04d',y),sprintf('%02d',m));if ~isfolder(statsdir),mkdir(statsdir);end;stage=fullfile(statsdir,['CALIPSO_STATS_Monthly_' ym '.mat']);build_calipso_stats_month(y,m,stage,'DateInventoryPath',dates_file);publish_calipso_stats_month(y,m,stage);
addpath(fullfile(project,'code','producers','ccn_grid'),'-begin');ccnstage_dir=fullfile(run_root,'staging','ccn_monthly',sprintf('%04d',y),sprintf('%02d',m));if ~isfolder(ccnstage_dir),mkdir(ccnstage_dir);end;ccnstage=fullfile(ccnstage_dir,['CCN_GRID_Monthly_' ym '.mat']);build_ccn_grid_monthly_from_daily(y,m,ccnstage,dates_file);publish_ccn_grid_month(y,m,ccnstage);
setenv('CHAPTER4_RUN_ID',run_id);setenv('CHAPTER4_YEAR',num2str(y));setenv('CHAPTER4_MONTH',num2str(m));run(fullfile(project,'code','batch','run_chapter4_month.m'));
